class _HomeScreenState extends State<HomeScreen>{int count=0;bool loading=true;@override void initState(){super.initState();load();}Future<void> load()async{try{final rows=await LocalDatabase.instance.resources();if(mounted)setState((){count=rows.length;loading=false;});}catch(_){if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('UMURAVA'),actions:const [Padding(padding:EdgeInsets.only(right:16),child:Icon(Icons.cloud_off_outlined))]),body:ListView(padding:const EdgeInsets.all(20),children:[Text('Community resilience network',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Local-first access to essential community resources.'),const SizedBox(height:24),Card(child:ListTile(leading:const Icon(Icons.storage_outlined),title:const Text('Resources stored on this device'),subtitle:Text(loading?'Checking local database…':'$count locally stored resource(s)'))),const Card(child:ListTile(leading:Icon(Icons.sync_outlined),title:Text('Synchronization'),subtitle:Text('Local outbox schema is prepared. Sync transport is planned for Sprint 03.'))),const Card(child:ListTile(leading:Icon(Icons.shield_outlined),title:Text('Security'),subtitle:Text('Do not store sensitive or patient information in this foundation build.')))]));}
